        {%- do match_tracking_select_element.append("T."~col~"_TRACK") -%}
    {%- endfor -%}

    {## From mini select statement #}
    {%- set match_tracking_from_mini_select_element = [] -%}
    {%- do match_tracking_from_mini_select_element.append(pk_key) -%}
