        {%- do match_tracking_from_mini_select_element.append("MAX(CASE WHEN "~col~"_RN = 1 THEN "~pk_key~"_REF ELSE NULL END) AS "~col~"_TRACK") -%}
    {%- endfor -%}


    {%- set match_tracking_element = [] -%}
    {%- do match_tracking_element.append("SELECT") -%}
    {%- do match_tracking_element.append(match_tracking_select_element|join(",\n")) -%}

    {%- do match_tracking_element.append("FROM (") -%}
    {%- do match_tracking_element.append("\tSELECT "~match_tracking_from_mini_select_element|join(",\n\t")) -%}

    {%- do match_tracking_element.append("\tFROM "~arrange_tbl~"") -%}
    {%- do match_tracking_element.append("\tGROUP BY "~pk_key~"") -%}
    {%- do match_tracking_element.append(") T") -%}
    {%- do match_tracking_element.append("JOIN "~arrange_tbl~" R ON T."~pk_key~" = R."~pk_key~"_REF") -%}

    {{ match_tracking_element|join("\n") }} 

{%- endmacro -%}

macro.ktl_dbt.oracle__ktl_mdm_auto_match.macro_sql:
{%- macro oracle__ktl_mdm_auto_match_tracking_list_aggregate_pk_ref_statement(p_pk_key) -%}
    {{ return("LISTAGG("~p_pk_key~"_REF, '|') WITHIN GROUP (ORDER BY "~p_pk_key~"_REF)") }}
{%- endmacro -%}

macro.ktl_dbt.ktl_mdm_match_arrange_mast.macro_sql:
{%- macro ktl_mdm_match_arrange_masterlist(general_conf,metadata_conf,rule_apply,validate_tbl_lastest,dup_tbl) -%}
    {# Metadata_config #}
    {%- set pk_key =  ktl_mdm_utils_metadata_get_pk_col(metadata_conf) -%}
    {%- set ldt_col =  ktl_mdm_utils_metadata_get_ldt_col(metadata_conf) -%}
    {%- set cob_col =  ktl_mdm_utils_metadata_get_cob_col(metadata_conf) -%}
    {%- set cob_value = ktl_mdm_utils_get_cob_value(general_conf) -%}

    {# Main handler #}
    {## CTE_VALIDATE_TBL_OF_AUTO_MATCH #}
    {%- set match_select_cte_vtbl_element = ["V_TBL."~pk_key] -%}
    {%- for col in ktl_mdm_utils_metadata_get_master_with_cdt_errcnt_lst(metadata_conf) -%}
        {%- if col|upper != pk_key -%}
            {%- do match_select_cte_vtbl_element.append("V_TBL."~col) -%}
        {%- endif -%}
    {%- endfor %}


    {%- set match_arrange_masterlist_element = [] -%}
    {%- do match_arrange_masterlist_element.append("WITH CTE_VALIDATE_TBL_OF_AUTO_MATCH AS (") -%}
    {%- do match_arrange_masterlist_element.append("\tSELECT "~match_select_cte_vtbl_element|join(",\n\t")~",") -%}
    {%- do match_arrange_masterlist_element.append("\tD_TBL."~cob_col~",") -%}
    {%- do match_arrange_masterlist_element.append("\tD_TBL.L_"~cob_col~",") -%}
    {%- do match_arrange_masterlist_element.append("\tD_TBL.HAS_AUTO_MATCH,") -%}
    {%- do match_arrange_masterlist_element.append("\tD_TBL.MANUAL_DUPLICATE_GROUP,") -%}
    {%- do match_arrange_masterlist_element.append("\tD_TBL.AUTO_DUPLICATE_GROUP") -%}
    {%- do match_arrange_masterlist_element.append("\tFROM "~dup_tbl~" D_TBL") -%}
    {%- do match_arrange_masterlist_element.append("\tJOIN "~validate_tbl_lastest~" V_TBL ON V_TBL."~pk_key~" = D_TBL."~pk_key~"") -%}
    {%- do match_arrange_masterlist_element.append("\tWHERE D_TBL.HAS_AUTO_MATCH = 1") -%}
    {%- do match_arrange_masterlist_element.append("),\n") -%}

    {## CTE_CHOOSE_KEY #}
    {### Choose key priority by  #}
    {%- set choose_key_priority_by_lst = [] -%}
    {%- for column, ord_type in rule_apply.get("auto_match_pkkey_priority_by").items() -%}
        {%- do choose_key_priority_by_lst.append(column~" "~ord_type|upper) -%}
    {%- endfor -%}
    {%- do choose_key_priority_by_lst.append(pk_key~" ASC") -%}


    {%- do match_arrange_masterlist_element.append("CTE_CHOOSE_KEY AS (") -%}
    {%- do match_arrange_masterlist_element.append("\tSELECT * FROM (") -%}
    {%- do match_arrange_masterlist_element.append("\t\tSELECT "~pk_key~",") -%}
    {%- do match_arrange_masterlist_element.append("\t\tMANUAL_DUPLICATE_GROUP,") -%}
    {%- do match_arrange_masterlist_element.append("\t\tAUTO_DUPLICATE_GROUP,") -%}
    {%- do match_arrange_masterlist_element.append("\t\t"~cob_col~",") -%}
    {%- do match_arrange_masterlist_element.append("\t\tL_"~cob_col~",") -%}
    {%- do match_arrange_masterlist_element.append("\t\tROW_NUMBER() OVER(PARTITION BY AUTO_DUPLICATE_GROUP ORDER BY "~choose_key_priority_by_lst|join(", ")~" ) "~pk_key~"_RN") -%} {# TODO #}
    {%- do match_arrange_masterlist_element.append("\t\tFROM CTE_VALIDATE_TBL_OF_AUTO_MATCH") -%}
    {%- do match_arrange_masterlist_element.append("\t) WHERE "~pk_key~"_RN = 1") -%}
    {%- do match_arrange_masterlist_element.append(")\n") -%}

    {## MAIN SELECT #}
    {%- set match_arrange_masterlist_select_element = ["\t"~ktl_mdm_utils_metadata_get_ldt_statement(ldt_col)] -%}
    {%- do match_arrange_masterlist_select_element.append("K_TBL."~cob_col) -%}
    {%- do match_arrange_masterlist_select_element.append("V_TBL.L_"~cob_col) -%}
    {%- do match_arrange_masterlist_select_element.append("K_TBL."~pk_key) -%}
    {%- do match_arrange_masterlist_select_element.append("V_TBL."~pk_key~" AS "~pk_key~"_REF") -%}
    {%- do match_arrange_masterlist_select_element.append("K_TBL.MANUAL_DUPLICATE_GROUP") -%}
    {%- do match_arrange_masterlist_select_element.append("K_TBL.AUTO_DUPLICATE_GROUP") -%}

    {%- for col in ktl_mdm_utils_metadata_get_master_with_cdt_errcnt_lst(metadata_conf) -%}
        {%- if col|upper != pk_key -%}
            {%- do match_arrange_masterlist_select_element.append("V_TBL."~col) -%}
        {%- endif -%}
    {%- endfor -%}

    {%- for col in ktl_mdm_utils_metadata_get_master_column_lst(metadata_conf) -%}
        {%- if ktl_mdm_utils_metadata_does_column_have_cdt(metadata_conf,col) == true -%}
            {%- do match_arrange_masterlist_select_element.append("ROW_NUMBER() OVER (PARTITION BY V_TBL.AUTO_DUPLICATE_GROUP ORDER BY SIGN(V_TBL."~col~"_ERR_CNT) ASC, V_TBL."~col~"_CDT DESC, (CASE WHEN V_TBL."~pk_key~" = K_TBL."~pk_key~" THEN 1 ELSE 0 END) DESC) AS "~col~"_RN") -%}
        {%- else -%}
            {%- do match_arrange_masterlist_select_element.append("ROW_NUMBER() OVER (PARTITION BY V_TBL.AUTO_DUPLICATE_GROUP ORDER BY SIGN(V_TBL."~col~"_ERR_CNT) ASC, (CASE WHEN V_TBL."~pk_key~" = K_TBL."~pk_key~" THEN 1 ELSE 0 END) DESC) AS "~col~"_RN") -%}
        {%- endif -%}
    {%- endfor -%}

    {%- do match_arrange_masterlist_element.append("SELECT") -%}
    {%- do match_arrange_masterlist_element.append(match_arrange_masterlist_select_element|join(",\n\t")) -%}
    {%- do match_arrange_masterlist_element.append("FROM CTE_CHOOSE_KEY K_TBL") -%}
    {%- do match_arrange_masterlist_element.append("JOIN CTE_VALIDATE_TBL_OF_AUTO_MATCH V_TBL") -%}
    {%- do match_arrange_masterlist_element.append("ON K_TBL.AUTO_DUPLICATE_GROUP = V_TBL.AUTO_DUPLICATE_GROUP") -%}

    {{ return(match_arrange_masterlist_element|join("\n")) }} 
{%- endmacro -%}

macro.ktl_dbt.ktl_mdm_match_duplicate.macro_sql:
{%- macro ktl_mdm_match_duplicate(general_conf,metadata_conf,rule_apply,source_system,dupno_tbl) -%}
    {# General_config #}
    {%- set match_column_cnt = general_conf.get('general_config').get('match_column_cnt') -%}
    {%- set match_group_cnt = general_conf.get('general_config').get('match_group_cnt') -%}

    {# Metadata_config #}
    {%- set pk_key =  ktl_mdm_utils_metadata_get_pk_col(metadata_conf) -%}
    {%- set ldt_col =  ktl_mdm_utils_metadata_get_ldt_col(metadata_conf) -%}
    {%- set cob_col =  ktl_mdm_utils_metadata_get_cob_col(metadata_conf) -%}
    {%- set cob_value = ktl_mdm_utils_get_cob_value(general_conf) -%}

    {# Main handler #}
    {%- set auto_rule_apply = ktl_mdm_match_utils_get_auto_match(rule_apply) -%}
    {%- set manual_rule_apply = ktl_mdm_match_utils_get_manual_match(rule_apply) -%}

    {# Select  #}
    {%- set match_duplicate_cte_select_count_over_element = [] -%}
    {%- set match_column_lst = [] -%}

    {%- for i in range(1,match_column_cnt+1) -%}
        {%- do match_column_lst.append('MATCH_COLUMN_'~i) -%}
        {%- do match_duplicate_cte_select_count_over_element.append("NVL(MATCH_COLUMN_"~i~",'')") -%}
    {%- endfor -%}

    {%- for i in range(1,match_group_cnt+1) -%}
        {%- do match_column_lst.append('MATCH_GROUP_'~i) -%}
        {%- do match_duplicate_cte_select_count_over_element.append("NVL(MATCH_GROUP_"~i~",'')") -%}
    {%- endfor -%}

    {%- set match_duplicate_summary_select_element = [pk_key,"L_"~cob_col,'RULE_CODE'] + match_column_lst -%}


    {%- set match_duplicate_cte_table_lst = [] -%}
    {# Each cte_tbl order rule auto #}
    {%- for i in range(auto_rule_apply|length)-%}
        {%- set match_duplicate_cte_where_element = ["RULE_CODE = '"~auto_rule_apply[i].get('name')~"'"] -%}
        {%- for j in range(i)-%}
            {%- do match_duplicate_cte_where_element.append("NOT EXISTS (SELECT 1 FROM CTE_AUTO_"~auto_rule_apply[j].get('name')~" T WHERE T.RULE_CODE ='"~auto_rule_apply[j].get('name')~"' AND T."~pk_key~" = dupno_tbl."~pk_key~")") -%}
        {%- endfor -%}

        {%- set match_duplicate_cte_table_element = [] -%}
        {%- do match_duplicate_cte_table_element.append("CTE_AUTO_"~auto_rule_apply[i].get('name')~" AS (") -%}
        {%- do match_duplicate_cte_table_element.append("\tSELECT * FROM (") -%}

        {%- do match_duplicate_cte_table_element.append("\t\tSELECT dupno_tbl.* , COUNT(1) OVER(PARTITION BY "~match_duplicate_cte_select_count_over_element|join(", ")~") CNT") -%}
        {%- do match_duplicate_cte_table_element.append("\t\tFROM "~dupno_tbl~" dupno_tbl") -%}
        {%- do match_duplicate_cte_table_element.append("\t\tWHERE "~match_duplicate_cte_where_element|join("\n\t\tAND ")) -%}
        {%- do match_duplicate_cte_table_element.append("\t) WHERE CNT > 1") -%}
        {%- do match_duplicate_cte_table_element.append(")") -%}

        {%- do match_duplicate_cte_table_lst.append(match_duplicate_cte_table_element|join("\n")) -%}
    {%- endfor -%}

    {# Each cte_tbl order rule manual #}
    {%- for i in range(manual_rule_apply|length)-%}
        {%- set match_duplicate_cte_where_element = ["RULE_CODE = '"~manual_rule_apply[i].get('name')~"'"] -%}
        {%- for j in range(i)-%}
            {%- do match_duplicate_cte_where_element.append("NOT EXISTS (SELECT 1 FROM CTE_MANUAL_"~manual_rule_apply[j].get('name')~" T WHERE T.RULE_CODE ='"~manual_rule_apply[j].get('name')~"' AND T."~pk_key~" = dupno_tbl."~pk_key~")") -%}
        {%- endfor -%}

        {%- set match_duplicate_cte_table_element = [] -%}
        {%- do match_duplicate_cte_table_element.append("CTE_MANUAL_"~manual_rule_apply[i].get('name')~" AS (") -%}
        {%- do match_duplicate_cte_table_element.append("\tSELECT * FROM (") -%}

        {%- do match_duplicate_cte_table_element.append("\t\tSELECT dupno_tbl.* , COUNT(1) OVER(PARTITION BY "~match_duplicate_cte_select_count_over_element|join(", ")~") CNT") -%}
        {%- do match_duplicate_cte_table_element.append("\t\tFROM "~dupno_tbl~" dupno_tbl") -%}
        {%- do match_duplicate_cte_table_element.append("\t\tWHERE "~match_duplicate_cte_where_element|join("\n\t\tAND ")) -%}
        {%- do match_duplicate_cte_table_element.append("\t) WHERE CNT > 1") -%}
        {%- do match_duplicate_cte_table_element.append(")") -%}

        {%- do match_duplicate_cte_table_lst.append(match_duplicate_cte_table_element|join("\n")) -%}
    {%- endfor -%}

    {# Summary auto rule #}
    {%- set match_duplicate_summary_select_statement = match_duplicate_summary_select_element|join(", ")%}

    {%- set match_summary_auto_table_element = [] -%}
    {%- set match_summary_mini_select_table_element = ["\tSELECT "~match_duplicate_summary_select_statement~"\n\tFROM "~dupno_tbl~" WHERE 1=0"] -%}

    {%- for i in range(auto_rule_apply|length)-%}
        {%- do match_summary_mini_select_table_element.append("\tSELECT "~match_duplicate_summary_select_statement~"\n\tFROM CTE_AUTO_"~auto_rule_apply[i].get('name')) -%}
    {%- endfor -%}

    {%- do match_summary_auto_table_element.append("CTE_AUTO_SUM AS (") -%}
    {%- do match_summary_auto_table_element.append(match_summary_mini_select_table_element|join("\n\tUNION ALL\n")) -%}
    {%- do match_summary_auto_table_element.append(")") -%}

    {%- do match_duplicate_cte_table_lst.append(match_summary_auto_table_element|join("\n")) -%}

    {# Summary manual rule #}
    {%- set match_duplicate_summary_select_statement = match_duplicate_summary_select_element|join(", ")%}

    {%- set match_summary_manual_table_element = [] -%}
    {%- set match_summary_mini_select_table_element = ["\tSELECT "~match_duplicate_summary_select_statement~"\n\tFROM "~dupno_tbl~" WHERE 1=0"] -%}

    {%- for i in range(manual_rule_apply|length)-%}
        {%- do match_summary_mini_select_table_element.append("\tSELECT "~match_duplicate_summary_select_statement~"\n\tFROM CTE_MANUAL_"~manual_rule_apply[i].get('name')) -%}
    {%- endfor -%}

    {%- do match_summary_manual_table_element.append("CTE_MANUAL_SUM AS (") -%}
    {%- do match_summary_manual_table_element.append(match_summary_mini_select_table_element|join("\n\tUNION ALL\n")) -%}
    {%- do match_summary_manual_table_element.append(")") -%}

    {%- do match_duplicate_cte_table_lst.append(match_summary_manual_table_element|join("\n")) -%}

    {# Duplicate auto rule #}
    {%- set match_auto_duplicate_table_element = [] -%}
    {%- set match_auto_duplicate_select_element = [pk_key,"L_"~cob_col,'RULE_CODE'] + match_column_lst %}


    {%- do match_auto_duplicate_select_element.append("COUNT("~pk_key~") OVER(PARTITION BY RULE_CODE, "~match_column_lst|join(", ")~") AS ELEMENT_CNT") -%}

    {%- set match_duplicate_hash_element = ["RULE_CODE"] %}
    {%- for i in match_column_lst -%}
        {%- do match_duplicate_hash_element.append("NVL("~i~",'000000000')") -%}
    {%- endfor -%} 

    {%- do match_auto_duplicate_select_element.append(ktl_mdm_match_duplicate_hash_statement(match_duplicate_hash_element|join(" || "))~" AS DUPLICATE_GROUP") -%}

    {%- do match_auto_duplicate_table_element.append("CTE_AUTO_DUPLICATE AS (") -%}

    {%- do match_auto_duplicate_table_element.append("\tSELECT") -%}
    {%- do match_auto_duplicate_table_element.append("\t"~match_auto_duplicate_select_element|join(",\n\t")) -%}
    {%- do match_auto_duplicate_table_element.append("\tFROM CTE_AUTO_SUM") -%}
    {%- do match_auto_duplicate_table_element.append(")") -%}

    {%- do match_duplicate_cte_table_lst.append(match_auto_duplicate_table_element|join("\n")) -%}


    {# Duplicate manual rule #}
    {%- set match_manual_duplicate_table_element = [] -%}
    {%- set match_manual_duplicate_select_element = [pk_key,"L_"~cob_col,'RULE_CODE'] + match_column_lst %}


    {%- do match_manual_duplicate_select_element.append("COUNT("~pk_key~") OVER(PARTITION BY RULE_CODE, "~match_column_lst|join(", ")~") AS ELEMENT_CNT") -%}

    {%- set match_duplicate_hash_element = ["RULE_CODE"] %}
    {%- for i in match_column_lst -%}
        {%- do match_duplicate_hash_element.append("NVL("~i~",'000000000')") -%}
    {%- endfor -%} 

    {%- do match_manual_duplicate_select_element.append(ktl_mdm_match_duplicate_hash_statement(match_duplicate_hash_element|join(" || "))~" AS DUPLICATE_GROUP") -%}

    {%- do match_manual_duplicate_table_element.append("CTE_MANUAL_DUPLICATE AS (") -%}

    {%- do match_manual_duplicate_table_element.append("\tSELECT") -%}
    {%- do match_manual_duplicate_table_element.append("\t"~match_manual_duplicate_select_element|join(",\n\t")) -%}
    {%- do match_manual_duplicate_table_element.append("\tFROM CTE_MANUAL_SUM") -%}
    {%- do match_manual_duplicate_table_element.append(")") -%}

    {%- do match_duplicate_cte_table_lst.append(match_manual_duplicate_table_element|join("\n")) -%}


    {# Main select #}
    {## General info  #}
    {%- set match_duplicate_main_select_element = [] -%}
    {%- do match_duplicate_main_select_element.append(ktl_mdm_utils_metadata_get_ldt_statement(ldt_col)) -%}
    {%- do match_duplicate_main_select_element.append("'"~source_system~"'"~" AS SOURCE_SYSTEM") -%}
    {%- do match_duplicate_main_select_element.append(cob_value~" AS "~cob_col) -%}

    {%- do match_duplicate_main_select_element.append("CASE WHEN MANUAL_TBL."~pk_key~" IS NOT NULL THEN MANUAL_TBL.L_"~cob_col~" ELSE AUTO_TBL.L_"~cob_col~" END AS L_"~cob_col) -%}
    {%- do match_duplicate_main_select_element.append("CASE WHEN MANUAL_TBL."~pk_key~" IS NOT NULL THEN MANUAL_TBL."~pk_key~" ELSE AUTO_TBL."~pk_key~" END AS "~pk_key) -%}

    {%- do match_duplicate_main_select_element.append("CASE WHEN MANUAL_TBL."~pk_key~" IS NOT NULL THEN 1 ELSE 0 END HAS_MANUAL_MATCH") -%}
    {%- do match_duplicate_main_select_element.append("MANUAL_TBL.RULE_CODE AS MANUAL_RULE_CODE") -%}

    {%- do match_duplicate_main_select_element.append("CASE WHEN AUTO_TBL."~pk_key~" IS NOT NULL THEN 1 ELSE 0 END HAS_AUTO_MATCH") -%}
    {%- do match_duplicate_main_select_element.append("AUTO_TBL.RULE_CODE AS AUTO_RULE_CODE") -%}

    {## Manual_tbl info  #}
    {%- for i in match_column_lst -%}
        {%- do match_duplicate_main_select_element.append("MANUAL_TBL."~i~" AS MANUAL_"~i) -%}
    {%- endfor -%}

    {%- do match_duplicate_main_select_element.append("MANUAL_TBL.ELEMENT_CNT AS MANUAL_ELEMENT_CNT") -%}
    {%- do match_duplicate_main_select_element.append("MANUAL_TBL.DUPLICATE_GROUP AS MANUAL_DUPLICATE_GROUP") -%}

    {## Auto_tbl info  #}
    {%- for i in match_column_lst -%}
        {%- do match_duplicate_main_select_element.append("AUTO_TBL."~i~" AS AUTO_"~i) -%}
    {%- endfor -%}

    {%- do match_duplicate_main_select_element.append("AUTO_TBL.ELEMENT_CNT AS AUTO_ELEMENT_CNT") -%}
    {%- do match_duplicate_main_select_element.append("AUTO_TBL.DUPLICATE_GROUP AS AUTO_DUPLICATE_GROUP") -%}


    {%- set match_duplicate_main_element = [] -%}
    {%- do match_duplicate_main_element.append("SELECT") -%}
    {%- do match_duplicate_main_element.append(match_duplicate_main_select_element|join(",\n")) -%}
    {%- do match_duplicate_main_element.append("FROM CTE_MANUAL_DUPLICATE MANUAL_TBL") -%}
    {%- do match_duplicate_main_element.append("FULL OUTER JOIN CTE_AUTO_DUPLICATE AUTO_TBL") -%}
    {%- do match_duplicate_main_element.append("ON MANUAL_TBL."~pk_key~" = AUTO_TBL."~pk_key~"") -%}

    {{ return("WITH "~match_duplicate_cte_table_lst|join(",\n\n") ~ "\n\n" ~ match_duplicate_main_element|join("\n")) }}
{%- endmacro -%}

macro.ktl_dbt.ktl_mdm_match_duplicate_no.macro_sql:
{%- macro ktl_mdm_match_duplicate_not_rule_order(general_conf,metadata_conf,rule_apply,validate_tbl_lastest,ldup_tbl) -%}
    {# General_config #}
    {%- set match_column_cnt = general_conf.get('general_config').get('match_column_cnt') -%}
    {%- set match_group_cnt = general_conf.get('general_config').get('match_group_cnt') -%}

    {# Metadata_config #}
    {%- set pk_key =  ktl_mdm_utils_metadata_get_pk_col(metadata_conf) -%}
    {%- set ldt_col =  ktl_mdm_utils_metadata_get_ldt_col(metadata_conf) -%}
    {%- set cob_col =  ktl_mdm_utils_metadata_get_cob_col(metadata_conf) -%}

    {# Main handler #}
    {%- set match_duplicate_not_order_element = [] -%}
    {%- for item in rule_apply.get('matched_by_rules') -%}
        {%- do match_duplicate_not_order_element.append(ktl_mdm_match_duplicate_not_order_element(item,match_column_cnt,match_group_cnt,validate_tbl_lastest,ldup_tbl,pk_key,ldt_col,cob_col)) -%}
    {%- endfor -%}
    {{ return(match_duplicate_not_order_element|join("\n\nUNION ALL\n\n")) }}
{%- endmacro -%}

{%- macro ktl_mdm_match_duplicate_not_order_element(rule_apply_item,match_column_cnt,match_group_cnt,validate_tbl_lastest,ldup_tbl,pk_key,ldt_col,cob_col) -%}
    {%- set select_element_lst = [] -%}

    {# SELECT statement #}
    {## RULE_CODE #}
    {%- do select_element_lst.append(ktl_mdm_utils_metadata_get_ldt_statement(ldt_col)) -%}
    {%- do select_element_lst.append(pk_key) -%}
    {%- do select_element_lst.append(cob_col~" AS L_"~cob_col) -%}
    {%- do select_element_lst.append("'"~rule_apply_item.get('name')~"' AS RULE_CODE") -%}    

    {## straight MATCH_COLUMN #}
    {%- if rule_apply_item.get('straight') is not none -%}
        {%- for i in range(1,match_column_cnt+1) -%}
            {%- set match_column = rule_apply_item.get('straight').get('match_column_'~i) -%}
            {%- if match_column is not none -%}
                {%- do select_element_lst.append("TBL."~match_column~" AS MATCH_COLUMN_"~i) -%}
            {%- else -%}
                {%- do select_element_lst.append("CAST(NULL AS "~ktl_mdm_utils_types_string(nbyte = 2000)~") AS MATCH_COLUMN_"~i) -%}
            {%- endif -%}        
        {%- endfor -%}
    {%- else -%}
        {%- for i in range(1,match_column_cnt+1) -%}
            {%- do select_element_lst.append("CAST(NULL AS "~ktl_mdm_utils_types_string(nbyte = 2000)~") AS MATCH_COLUMN_"~i) -%}
        {%- endfor -%}
    {%- endif -%}

    {## cross MATCH_COLUMN #}
    {%- if rule_apply_item.get('cross') is not none -%}
        {%- for i in range(1,match_group_cnt+1) -%}
            {%- set match_group = rule_apply_item.get('cross').get('match_group_'~i) -%}
            {%- if match_group is not none -%}
                {%- do select_element_lst.append("MATCH_GROUP_"~i~" AS MATCH_GROUP_"~i) -%}
            {%- else -%}
                {%- do select_element_lst.append("CAST(NULL AS "~ktl_mdm_utils_types_string(nbyte = 2000)~") AS MATCH_GROUP_"~i) -%}
            {%- endif -%}        
        {%- endfor -%}
    {%- else -%}
        {%- for i in range(1,match_group_cnt+1) -%}
            {%- do select_element_lst.append("CAST(NULL AS "~ktl_mdm_utils_types_string(nbyte = 2000)~") AS MATCH_GROUP_"~i) -%}
        {%- endfor -%}
    {%- endif -%}


    {# FROM statement #}
    {%- if rule_apply_item.get('cross') is not none -%}
        {## exists cross #}
        {%- set from_element_lst = [] -%}
        {%- set all_match_group = ktl_mdm_match_duplicate_not_order_get_all_cross_group(rule_apply_item,match_group_cnt) -%}
        {%- set combination_lst = ktl_mdm_match_duplicate_not_order_combination_cross_group(all_match_group) -%}
        {%- for combination in combination_lst -%}

            {%- set mini_from_where_exists_lst = [] -%}
            {%- set mini_from_select_lst = [] -%}
            {%- do mini_from_select_lst.append("T."~pk_key) -%}
            {%- do mini_from_select_lst.append("T."~cob_col) -%}

            {%- for i in range(combination|length) -%}
                {%- do mini_from_select_lst.append("T."~combination[i] ~" AS MATCH_GROUP_"~(i+1)) -%}
                {%- do mini_from_where_exists_lst.append("T."~combination[i] ~" = FLDUP_TBL.MATCH_GROUP_"~(i+1)) -%}
            {%- endfor -%}

            {%- set mini_from_lst = [] -%}
            {%- do mini_from_lst.append("\tSELECT "~mini_from_select_lst|join(",\n\t")) -%}
            {%- do mini_from_lst.append("\tFROM "~validate_tbl_lastest~" T") -%}
            {%- do mini_from_lst.append("\tWHERE EXISTS (") -%}
            {%- do mini_from_lst.append("\t\tSELECT 1 from "~ldup_tbl~" FLDUP_TBL") -%}
            {%- do mini_from_lst.append("\t\tWHERE "~mini_from_where_exists_lst|join("\n\t\tAND ")) -%}
            {%- do mini_from_lst.append("\t)") -%}
            {%- do from_element_lst.append(mini_from_lst|join("\n")) -%}        
        {%- endfor -%}

        {%- set from_statement = from_element_lst|join("\n\n\tUNION ALL\n\n") -%}

    {%- else -%}
        {## straight only #}
        {%- set from_statement = '\tSELECT * FROM ' ~ validate_tbl_lastest -%}
    {%- endif -%}

    {# WHERE statement #}
    {%- set where_statement = "1=1" -%} 
    {%- if rule_apply_item.get('straight') is not none -%}
        {%- set where_exists_lst = [""] -%}
        {%- do where_exists_lst.append("AND EXISTS (") -%}
        {%- do where_exists_lst.append("\tSELECT 1 FROM "~ldup_tbl~" LD_TBL") -%}

        {## WHERE exists statement #}
        {%- set mini_where_exists_where_element = [] -%}
        {%- for i in range(1,match_column_cnt+1) -%}
            {%- set match_column = rule_apply_item.get('straight').get('match_column_'~i) -%}
            {%- if match_column is not none -%}
                {%- do mini_where_exists_where_element.append("TBL."~match_column~" = LD_TBL.MATCH_COLUMN_"~i) -%}
            {%- endif -%}        
        {%- endfor -%}
        {%- do where_exists_lst.append("\tWHERE "~mini_where_exists_where_element|join("\n\tAND ")) -%}
        {%- do where_exists_lst.append(")") -%}
        {%- set where_statement = where_statement~where_exists_lst|join('\n') -%}
    {%- endif -%}

    {# Generate SQL of match element #}
    {%- set result_lst = [] -%}
    {%- do result_lst.append("SELECT DISTINCT") -%}
    {%- do result_lst.append(select_element_lst|join(",\n")) -%}
    {%- do result_lst.append("FROM (\n"~from_statement~"\n) TBL ") -%}
    {%- do result_lst.append("WHERE "~where_statement) -%}


    {{return (result_lst|join("\n"))}}

{%- endmacro -%}

{%- macro ktl_mdm_match_duplicate_not_order_combination_cross_group(match_group) -%}
    {%- if not match_group -%}
        {{ return([()]) }}
    {%- endif -%}

    {%- set combinations = [] -%}
    {%- set first_group = match_group[0] -%}
    {%- set rest_groups = match_group[1:] -%}
    {%- for item in first_group -%}
        {%- for combo in ktl_mdm_match_duplicate_not_order_combination_cross_group(rest_groups) -%}
            {%- do combinations.append((item,) + combo) -%}
        {%- endfor -%}
    {%- endfor -%}
    {{ return(combinations) }}
{%- endmacro -%}

{%- macro ktl_mdm_match_duplicate_not_order_get_all_cross_group(rule_apply_item,match_group_cnt) -%}
    {%- set group_lst = [] -%}

    {%- for i in range(1,match_group_cnt+1) -%}
        {%- if rule_apply_item.get('cross') is not none -%}
            {%- set match_group = rule_apply_item.get('cross').get('match_group_'~i) -%}
            {%- if match_group is not none -%}
                {%- if match_group|length != 0 -%}
                    {%- do group_lst.append(match_group) -%}
                {%- endif -%}   
            {%- endif -%}  
        {%- endif -%}      
    {%- endfor -%}
    {{ return(group_lst) }}
{%- endmacro -%}

macro.ktl_dbt.ktl_mdm_match_list_dup.macro_sql:
{%- macro ktl_mdm_match_list_dup(general_conf,metadata_conf,rule_apply,validate_tbl_lastest,validate_tbl_incre) -%}
