{%- endmacro -%}

macro.ktl_dbt.shb_validate_pass_i_dt_ran.macro_sql:
{%- macro shb_validate_pass_i_dt_range(pass_i_dt_col, d_o_b_col, cif_no_col, source_table) -%}
    {%- set open_date_column = 'OPEN_DATE' -%}

    LEFT JOIN (
        SELECT 
            CIF_NO,
            {{ open_date_column }} as CIF_OPEN_DATE
        FROM {{ source_table }}
    ) src_open
    ON {{ cif_no_col }} = src_open.CIF_NO
    WHERE 
        {{ pass_i_dt_col }} IS NOT NULL 
        AND (
            {{ pass_i_dt_col }} < {{ d_o_b_col }}
            OR {{ pass_i_dt_col }} > COALESCE(src_open.CIF_OPEN_DATE, CURRENT_DATE)
        )
{%- endmacro -%}

macro.ktl_dbt.apply_cleansing_rules.macro_sql:
{%- macro apply_cleansing_rules(source_ref, product='CORECIF', source_system='SHB') -%}

{%- set all_rules = mdm_get_cleansing_rules(product, source_system) -%}
{%-set all_columns = mdm_get_all_columns(product, source_system) -%}

WITH source_data AS (
    SELECT * FROM {{ source_ref }}
)

{%- for rule in all_rules %}
, {{ rule.code }}_applied AS (
    SELECT
    {%- for col in all_columns %}
        {%- if col in rule.columns %}
            {%- if rule.template == 'cleantp_replace_category' %}
        COALESCE(cat_{{ rule.code }}_{{ col }}.STANDARD_VALUE, source.{{ col }}) AS {{ col }}
            {%- elif rule.template == 'cleantp_remove_pattern' %}
        REGEXP_REPLACE(source.{{ col }}, '{{ rule.character }}', '') AS {{ col }}
            {%- elif rule.template == 'cleantp_format_datetime' %}
        TO_DATE(SUBSTR(source.{{ col }}, 1, 10), '{{ rule.from_str_format }}') AS {{ col }}
            {%- else %}
        source.{{ col }}
            {%- endif %}
        {%- else %}
        source.{{ col }}
        {%- endif %}
        {%- if not loop.last %},{% endif %}
    {%- endfor %}
    FROM {% if loop.first %}source_data{% else %}{{ all_rules[loop.index0 - 1].code }}_applied{% endif %} source
    {%- if rule.template == 'cleantp_replace_category' %}
        {%- for col in rule.columns %}
    LEFT JOIN {{ ref('mdm_catalog_category') }} cat_{{ rule.code }}_{{ col }}
        ON LOWER(source.{{ col }}) = LOWER(cat_{{ rule.code }}_{{ col }}.ORIGINAL_VALUE)
        AND cat_{{ rule.code }}_{{ col }}.CATEGORY_TYPE = LOWER('{{ rule.column_condition.split(':')[1] }}')
        AND LOWER(cat_{{ rule.code }}_{{ col }}.SOURCE_SYSTEM) = LOWER('{{ source_system }}')
        {%- endfor %}
    {%- endif %}
)
{%- endfor %}

SELECT * FROM {{ all_rules[-1].code }}_applied

{%- endmacro -%}

macro.ktl_dbt.mdm_get_match_rules.macro_sql:
{%- macro mdm_get_match_rules(product, source_system) -%}
    {%- set rule_desc_config = shb_rule_desc_config_yml() -%}

    {%- set rules = [] -%}
    {%- if rule_desc_config.match is defined -%}
        {%- for rule in rule_desc_config.match -%}
            {%- set rule_info = {
                'code': rule.code,
                'description': rule.description,
                'match_columns': rule.match_columns,
                'customer_type_filter': rule.get('customer_type_filter')
            } -%}
            {%- do rules.append(rule_info) -%}
        {%- endfor -%}
    {%- endif -%}

    {{ return(rules) }}
{%- endmacro -%}

macro.ktl_dbt.generate_match_flags.macro_sql:
{%- macro generate_match_flags(source_ref, product='CORECIF', source_system='SHB') -%}

{%- set match_rules = mdm_get_match_rules(product, source_system) -%}
{%- set all_columns = mdm_get_all_columns(product, source_system) -%}

SELECT
    base.*,
    {%- for rule in match_rules %}
    CASE
        WHEN COUNT(*) OVER (
            PARTITION BY 
                {%- if rule.customer_type_filter %}
                CASE WHEN base.CUSTOMER_TYPE = '{{ rule.customer_type_filter }}' THEN 1 ELSE 0 END,
                {%- endif %}
                {%- for col in rule.match_columns %}
                base.{{ col }}{% if not loop.last %},{% endif %}
                {%- endfor %}
        ) > 1
        {%- if rule.customer_type_filter %}
        AND base.CUSTOMER_TYPE = '{{ rule.customer_type_filter }}'
        {%- endif %}
        {%- for col in rule.match_columns %}
        AND base.{{ col }} IS NOT NULL
        {%- endfor %}
        THEN 1
        ELSE 0
    END AS FLAG_DUP_{{ rule.code }}
    {%- if not loop.last %},{% endif %}
    {%- endfor %}
FROM {{ source_ref }} base

{%- endmacro -%}

macro.ktl_dbt.generate_validation_sql.macro_sql:
{%- macro generate_validation_sql(source_ref, product='CORECIF', source_system='SHB', original_source_ref='') -%}

{%- set all_rules = mdm_get_validation_rules(product, source_system) -%}
{%- set pk_col = mdm_get_pk_column(product, source_system) -%}

{# Build list of SQL statements #}
{%- set sql_statements = [] -%}

{%- for rule in all_rules %}
    {%- for column in rule.columns %}
        {%- set use_original = ((rule.validate_original == 'YES' or rule.validate_original == true) and original_source_ref != '') -%}
        {%- set col_reference = 'orig.' ~ column if use_original else 'cleansed.' ~ column -%}
        {%- set where_clause = '' -%}

        {%- if rule.template == 'check_null' -%}
            {%- set where_clause = col_reference ~ " IS NULL OR LOWER(" ~ col_reference ~ ") = 'null' OR " ~ col_reference ~ " = ' '" -%}
        {%- elif rule.template == 'check_date_conversion' -%}
            {%- set where_clause = col_reference ~ " IS NOT NULL AND TO_DATE(SUBSTR(" ~ col_reference ~ ", 1, 10), '" ~ rule.date_format ~ "') IS NULL" -%}
        {%- elif rule.template == 'validatetp_regex_not_like' -%}
            {%- set where_clause = "COALESCE(" ~ col_reference ~ ", 'NULL') <> 'NULL' AND NOT REGEXP_LIKE(" ~ col_reference ~ ", '" ~ rule.regex_pattern ~ "')" -%}
        {%- elif rule.template == 'check_invalid_category' -%}
            {%- set cat_type = rule.column_condition.split(':')[1] -%}
            {%- set where_clause = col_reference ~ " NOT IN (SELECT DISTINCT STANDARD_VALUE FROM " ~ ref('mdm_catalog_category') ~ " WHERE CATEGORY_TYPE = '" ~ cat_type ~ "' AND SOURCE_SYSTEM = '" ~ source_system ~ "')" -%}
        {%- elif rule.template == 'check_active_datetime_legal_id' -%}
            {%- set months = rule.condition.split(':')[0] | int * 12 -%}
            {%- set where_clause = "cleansed.LOAI_GTTT IN ('CCCD') AND cleansed.PASS_E_DT IS NOT NULL AND cleansed.PASS_I_DT IS NOT NULL AND cleansed.PASS_E_DT <> add_months(cleansed.PASS_I_DT, " ~ months ~ ")" -%}
        {%- elif rule.template == 'check_legal_id_range_datetime_with_open_date' -%}
            {%- set where_clause = col_reference ~ " IS NOT NULL AND cleansed." ~ rule.column_condition ~ " IS NOT NULL AND " ~ col_reference ~ " <= cleansed." ~ rule.column_condition -%}
        {%- elif rule.template == 'validatetp_pass_no_by_loai_gttt' -%}
            {%- set where_clause = "(cleansed.LOAI_GTTT IN ('CCCD') AND (NOT REGEXP_LIKE(" ~ col_reference ~ ", '[^0-9]') AND LENGTH(" ~ col_reference ~ ") <> 12 OR REGEXP_LIKE(" ~ col_reference ~ ", '[^0-9]'))) OR (cleansed.LOAI_GTTT IN ('CMT') AND (NOT REGEXP_LIKE(" ~ col_reference ~ ", '^[^0-9]') AND LENGTH(" ~ col_reference ~ ") NOT IN (9,12) OR REGEXP_LIKE(" ~ col_reference ~ ", '[^0-9]')))" -%}
        {%- else -%}
            {%- set where_clause = "1=0 -- Unknown template: " ~ rule.template -%}
        {%- endif -%}


        {%- set table_name = original_source_ref.identifier if (use_original and original_source_ref.identifier) else (original_source_ref | string).split('.')[-1] if use_original else (source_ref.identifier if source_ref.identifier else (source_ref | string).split('.')[-1]) -%}

        {%- set sql_stmt -%}
SELECT
    cleansed.{{ pk_col }} AS {{ pk_col }},
    '{{ table_name }}' AS `TABLE`,
    '{{ column }}' AS `COLUMN`,
    '{{ rule.code }}' AS `RULE`,
    CAST({{ col_reference }} AS STRING) AS `VALUE`
FROM {{ source_ref }} cleansed
{%- if use_original %}
LEFT JOIN {{ original_source_ref }} orig
    ON cleansed.{{ pk_col }} = orig.{{ pk_col }}
{%- endif %}
WHERE {{ where_clause }}
        {%- endset -%}

        {%- do sql_statements.append(sql_stmt) -%}
    {%- endfor %}
{%- endfor %}

{# Join all statements with UNION ALL #}
{{ sql_statements | join('\nUNION ALL\n') }}

{%- endmacro -%}

macro.ktl_dbt.mdm_get_cleansing_rules.macro_sql:
