macro.ktl_autovault.lsate_transform.macro_sql:
{% macro lsate_transform(model, dv_system, from_ref_model=false) -%}

    {%- set lnk_table_name = ktl_autovault.render_target_table_name(model) -%}

    {%- set hkey_lnk_name = ktl_autovault.render_hash_key_lnk_name(model) -%}
    {%- set hkey_drv_name = ktl_autovault.render_hash_key_drv_name(model) -%}
    {%- set ldt_keys = ktl_autovault.render_list_dv_system_ldt_key_name(dv_system) -%}
    {%- set src_ldt_keys = ktl_autovault.render_list_source_ldt_key_name(dv_system) -%}

    with
        cte_stg_lsate as (
            select
                {{ ktl_autovault.render_hash_key_drv_treatment(model) }},
                {{ ktl_autovault.render_hash_key_lnk_treatment(model) }},
                {{ src_ldt_keys[0] }} as dv_startts,

                {% for expr in ktl_autovault.render_list_dv_system_column_treatment(dv_system) -%}
                    {{ expr }} {{- ',' if not loop.last }}
                {% endfor %}
            from
                {{ ktl_autovault.render_source_table_name(model, from_ref_model) }}
            where
                1 = 1
                {% for expr in ktl_autovault.render_list_hash_key_drv_component(model) -%}
                    and {{ expr }} is not null
                {% endfor %}

                {%- if is_incremental() -%}
                    and {{ src_ldt_keys[0] }} > coalesce((select max({{ ldt_keys[0] }}) from {{ this }}), {{ ktl_autovault.timestamp('1900-01-01') }})
                {%- endif %}
        ),

        {%- if is_incremental() %}

        cte_current_effectivity as (
            select
                lnk.{{ hkey_drv_name }},
                lsate.{{ hkey_lnk_name }},
                lsate.dv_startts
            from
                (
                    select *
                    from
                        (
                            select
                                {{ hkey_lnk_name }},
                                dv_startts,
                                dv_endts,

                                row_number() over (
                                    partition by {{ hkey_lnk_name }}
                                    order by
                                        {% for key in ldt_keys -%}
                                            {{ key }} desc {{- ',' if not loop.last }}
                                        {% endfor %}
                                ) as row_num

                            from {{ this }}
                        ) lsate
                    where
                        row_num = 1
                        and dv_endts = {{ ktl_autovault.timestamp('9999-12-31') }}
                ) lsate
            join
                {{ lnk_table_name }} lnk
                    on lsate.{{ hkey_lnk_name }} = lnk.{{ hkey_lnk_name }}
        ),

        cte_close_driver_key as (
            select
                {{ hkey_drv_name }},
                {{ hkey_lnk_name }},
                dv_startts,

                {% for expr in ktl_autovault.render_list_dv_system_column_name(dv_system) -%}
                    {{ expr }} {{- ',' if not loop.last }}
                {% endfor %}
            from
                (
                    select
                        *,
                        row_number() over (
                            partition by {{ hkey_drv_name }}
                            order by
                                {% for key in ldt_keys -%}
                                    {{ key }} desc {{- ',' if not loop.last }}
                                {% endfor %}
                        ) as row_num

                    from cte_stg_lsate
                ) stg
            where
                row_num = 1
        ),

        cte_close_effectivity as (
            select
                curr.{{ hkey_lnk_name }},
                curr.dv_startts,
                drv.dv_startts as dv_endts,

                {% for expr in ktl_autovault.render_list_dv_system_column_name(dv_system) -%}
                    drv.{{ expr }} {{- ',' if not loop.last }}
                {% endfor %}
            from
                cte_current_effectivity curr
                join cte_close_driver_key drv
                    on curr.{{ hkey_drv_name }} = drv.{{ hkey_drv_name }}
                    and curr.{{ hkey_lnk_name }} != drv.{{ hkey_lnk_name }}
        ),

        {%- endif %}

        cte_new_effectivity as (
            select
                {{ hkey_lnk_name }},
                dv_startts,

                lead(dv_startts, 1, {{ ktl_autovault.timestamp('9999-12-31') }}) over (
                    partition by {{ hkey_drv_name }}
                    order by
                        {% for key in ldt_keys -%}
                            {{ key }} asc {{- ',' if not loop.last }}
                        {% endfor %}
                ) dv_endts,

                {% for expr in ktl_autovault.render_list_dv_system_column_name(dv_system) -%}
                    {{ expr }} {{- ',' if not loop.last }}
                {% endfor %}
            from
                (
                    select
                        *,

                        lag({{ hkey_lnk_name }}, 1, {{ ktl_autovault.render_hash_key_lnk_ghost_record(model) }}) over (
                            partition by {{ hkey_drv_name }}
                            order by
                                {% for key in ldt_keys -%}
                                    {{ key }} asc {{- ',' if not loop.last }}
                                {% endfor %}
                        ) as prev_hkey_lnk

                    from cte_stg_lsate
                ) subq
            where
                prev_hkey_lnk != {{ hkey_lnk_name }}
        )

    select *
    from cte_new_effectivity lsate
    where
        exists (
            select 1
            from {{ lnk_table_name }} lnk
            where lsate.{{ hkey_lnk_name }} = lnk.{{ hkey_lnk_name }}
        )

    {%- if is_incremental() %}

    union all

    select * from cte_close_effectivity

    {%- endif -%}

{%- endmacro %}

macro.ktl_autovault.lsat_der_transform.macro_sql:
{% macro lsat_der_transform(
    model,
    dv_system,
    from_ref_model=false,
    initial_date = var('initial_date', run_started_at.astimezone(modules.pytz.timezone("Asia/Ho_Chi_Minh")).strftime('%Y-%m-%d'))
) -%}

    {#-
        This macro is used to transform a single source table into a LSAT-derivative table.
        Derivative tables are used to process raw data into LSAT-suitable format in real-time,
        before being loaded into the main LSAT table in EOD process.
        This approach allows for faster processing and more efficient data handling with large datasets.

        Arguments:
            model (dict): The model configuration, including target, source, and business key definitions.
            dv_system (dict): The system columns configuration, can be defined as project variables in the dbt_project.yml file.
            from_ref_model (bool): Indicates if the source table is a dbt ref model (true) or source model (false).
                If true, the source_schema is not needed. Defaults to false.
            initial_date (str): The initial date for the initial load. Defaults to the current date in 'Asia/Ho_Chi_Minh' timezone.
                This can be ignored if the ref_eod_table is provided as a project variable in dbt_project.yml.

        Example:
            {%- set model_yml -%}
            # this template is used for all type of LSAT tables: lsat, lsat_snp, lsat_der

            target_entity_type: lsat
            target_schema: integration
            target_table: lsat_customer_account
            parent_table: lnk_customer_account
            source_schema: source
            source_table: psa_loan_info
            collision_code: mdm
            columns:
              # required keys: hash_key_sat, hash_key_lnk, hash_diff, at least one undefined (normal attribute)
              # optional keys: depentent_key
              - target: dv_hkey_lsat_customer_account
                dtype: string
                key_type: hash_key_sat

              - target: dv_hkey_lnk_customer_account
                dtype: string
                key_type: hash_key_lnk
                source:
                  - ln_ac_nbr
                  - cst_no

              - target: dv_hsh_dif
                dtype: string
                key_type: hash_diff

              - target: br_cd
                dtype: decimal(38,0)
                source:
                  name: br_cd
                  dtype: string

              - target: book_date
                dtype: date
                source:
                  name: book_date
                  dtype: string

              - target: value_date
                dtype: date
                source:
                  name: value_date
                  dtype: string

            {%- endset -%}

            {%- set lsat_model = fromyaml(model_yml) -%}
            {%- set dv_system = var("dv_system") -%}
            {{ ktl_autovault.lsat_der_transform(model=lsat_model, dv_system=dv_system) }}
    -#}

    {%- if var('ref_eod_table', none) -%}
        {%- set initial_date = ktl_autovault.eod_initial_date(ref(var('ref_eod_table'))) -%}
    {%- endif -%}

    {%- set src_hkey_lnk = ktl_autovault.render_list_hash_key_lnk_component(model) -%}
    {%- set src_dep_keys = ktl_autovault.render_list_source_dependent_key_name(model) -%}
    {%- set src_ldt_keys = ktl_autovault.render_list_source_ldt_key_name(dv_system) -%}
    {%- set ldt_keys = ktl_autovault.render_list_dv_system_ldt_key_name(dv_system) -%}

    select
        {{ ktl_autovault.render_hash_key_lsat_treatment(model, dv_system) }},
        {{ ktl_autovault.render_hash_key_lnk_treatment(model) }},
        {{ ktl_autovault.render_hash_diff_treatment(model) }},

        {% for expr in ktl_autovault.render_list_dependent_key_treatment(model) -%}
            {{ expr }},
        {% endfor %}

        {% for expr in ktl_autovault.render_list_attr_column_treatment(model) -%}
            {{ expr }},
        {% endfor %}

        {% for expr in ktl_autovault.render_list_dv_system_column_treatment(dv_system) -%}
            {{ expr }} {{- ',' if not loop.last }}
